# Compute sum of column 'Seats' grouped by 'Party'
print(f"🔧 Computing sum of 'Seats' grouped by 'Party'")

# Check if columns exist and operation is valid
if 'Seats' not in df.columns:
    print(f"❌ Error: Column 'Seats' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif 'Party' not in df.columns:
    print(f"❌ Error: Group by column 'Party' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif "sum" not in ['count', 'sum', 'avg', 'min', 'max']:
    print(f"❌ Error: Invalid operation 'sum'. Valid operations: ['count', 'sum', 'avg', 'min', 'max']")
else:
    try:
        if "sum" == "count":
            result = df.groupby('Party')['Seats'].count()
        elif "sum" == "sum":
            result = df.groupby('Party')['Seats'].sum()
        elif "sum" == "avg":
            result = df.groupby('Party')['Seats'].mean()
        elif "sum" == "min":
            result = df.groupby('Party')['Seats'].min()
        elif "sum" == "max":
            result = df.groupby('Party')['Seats'].max()

        print(f"✅ Sum of 'Seats' by 'Party':")
        print(result)

        # Convert to dataframe for consistency
        result_df = result.reset_index()
        result_df.columns = ['Party', f'sum_result']
        print(f"\n🔍 Result as table:")
        print(result_df)

    except Exception as e:
        print(f"❌ Error computing grouped sum: {e}")
        print(f"Column dtypes: {df[['Seats', 'Party']].dtypes}")
